draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 50 + 20 * Math.sin(t), H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 50 - 20 * Math.sin(t), H/2 + 80);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 - 30 + 15 * Math.cos(t), H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 + 30 - 15 * Math.cos(t), H/2 + 120);
  ctx.stroke();

  // life event changing moment
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1280', W/2, H/2 - 50 + 20 * Math.sin(t));

  ctx.restore();
}
